select replace(replace(table_name,'OPENALEX_',''),'_INDEX','') as t, column_name as c, data_type as d from snowflake_public_data_free.information_schema.columns where table_schema = 'PUBLIC_DATA_FREE' and table_name in ('OPENALEX_AUTHORS_INDEX','OPENALEX_CONCEPTS_INDEX','OPENALEX_FUNDERS_INDEX','OPENALEX_INSTITUTIONS_INDEX','OPENALEX_PUBLISHERS_INDEX','OPENALEX_SOURCES_INDEX','OPENALEX_WORKS_INDEX') order by table_name, ordinal_position;